import socket, struct

def recvn(s, n):
    buf=b''
    while len(buf)<n:
        chunk=s.recv(n-len(buf))
        if not chunk: return buf
        buf+=chunk
    return buf

def probe(host, port, major, minor, ciphers=None, timeout=4):
    s=socket.socket(); s.settimeout(timeout)
    try:
        s.connect((host,port))
        ver=bytes([major,minor])
        ciphers = b'\x00\x2f' if ciphers is None else b''.join(struct.pack('!H',c) for c in ciphers)
        body = ver + b'\x01'*32 + b'\x00' + struct.pack('!H',len(ciphers)) + ciphers + b'\x01\x00' + b'\x00\x00'
        hs = b'\x01' + struct.pack('!I',len(body))[1:] + body
        s.sendall(b'\x16'+ver+struct.pack('!H',len(hs))+hs)
        hdr=recvn(s,5)
        if len(hdr)<5: return 'CLOSED', f'{hdr.hex()}'
        ct, lver, ln = hdr[0], hdr[1:3], struct.unpack('!H',hdr[3:5])[0]
        payload=recvn(s,ln)
        if ct==21:
            return 'ALERT', f'level={payload[0]} desc=0x{payload[1]:02x}'
        if ct==22:
            return 'SERVER_HELLO', payload[:2].hex()
        return f'CT_{ct}', payload.hex()
    except socket.timeout:
        return 'TIMEOUT','no response'
    except OSError as e:
        return 'TCP_ERROR', type(e).__name__+': '+str(e)
    finally:
        s.close()

print('modern TLS1.0      ->', probe('127.0.0.1',14443,3,1))
