print('legacy TLS1.2      ->', probe('127.0.0.1',14444,3,3))
print('closed port        ->', probe('127.0.0.1',1,3,3))
print('modern ok TLS1.2   ->', probe('127.0.0.1',14443,3,3))
EOF"}

